const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    const parts = line.split(' ').map(Number);
    const [n, k, l, c, d, p, nl, np] = parts;

    // Total toasts possible based on each resource
    const toastsFromDrink = Math.floor((k * l) / nl);
    const toastsFromLime = c * d;
    const toastsFromSalt = Math.floor(p / np);

    // Total toasts possible
    const totalToasts = Math.min(toastsFromDrink, toastsFromLime, toastsFromSalt);

    // Each friend gets the same number of toasts
    const toastsPerFriend = Math.floor(totalToasts / n);

    console.log(toastsPerFriend);
});
