const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const parts = line.split(' ').map(Number);
    const [n, k, l, c, d, p, nl, np] = parts;

    // Total milliliters of drink
    const totalDrink = k * l;
    // Total slices of lime
    const totalLime = c * d;
    // Total grams of salt
    const totalSalt = p;

    // Number of toasts possible with drink
    const toastsWithDrink = Math.floor(totalDrink / nl);
    // Number of toasts possible with lime
    const toastsWithLime = Math.floor(totalLime / 1); // each toast needs 1 slice
    // Number of toasts possible with salt
    const toastsWithSalt = Math.floor(totalSalt / np);

    // Total toasts that can be made
    const totalToasts = Math.min(toastsWithDrink, toastsWithLime, toastsWithSalt);

    // Each friend makes the same number of toasts
    const toastsPerFriend = Math.floor(totalToasts / n);

    console.log(toastsPerFriend);
});
```

